1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
31	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
32	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
33	// 任一配方版本的任一物料每份克数不是正数，
34	// 任一配方版本内同一物料编号出现多次，
35	// 任一批次绑定的配方版本未登记，
36	// 任一批次的计划份数不是正整数，或按其绑定的配方版本计算时某物料的
37	// 应投量（每份克数 × 计划份数）无法精确表示到千分之一克或超过
38	// 9223372036854775.807 克，
39	// 任一批次仍为草稿状态却带有投料记录，
40	// 已保存投料的物料编号不属于该批次绑定的配方版本，
41	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
42	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
43	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
44	func Open(dir string) (*Store, error) {
45		if dir == "" {
46			return nil, errors.New("数据位置不能为空")
47		}
48		if err := os.MkdirAll(dir, 0o755); err != nil {
49			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
50		}
51		info, err := os.Stat(dir)
52		if err != nil {
53			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
54		}
55		if !info.IsDir() {
56			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
57		}
58	
59		lockPath := filepath.Join(dir, lockFileName)
60		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
61		if err != nil {
62			return nil, fmt.Errorf("打开锁文件失败: %w", err)
63		}
64	
65		s := &Store{dir: dir, lockFile: lf}
66		if err := s.load(); err != nil {
67			lf.Close()
68			return nil, err
69		}
70		return s, nil
71	}
72	
73	// Close 释放台账占用的文件锁。
74	func (s *Store) Close() error {
75		s.mu.Lock()
76		defer s.mu.Unlock()
77		if s.lockFile == nil {
78			return nil
79		}
80		err := s.lockFile.Close()
81		s.lockFile = nil
82		return err
83	}
84	
85	func (s *Store) lockExclusive() error {
86		if s.lockFile == nil {
87			return errors.New("台账已关闭")
88		}
89		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
90			return fmt.Errorf("锁定台账失败: %w", err)
91		}
92		return nil
93	}
94	
95	func (s *Store) lockShared() error {
96		if s.lockFile == nil {
97			return errors.New("台账已关闭")
98		}
99		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
100			return fmt.Errorf("锁定台账失败: %w", err)
101		}
102		return nil
103	}
104	
105	func (s *Store) unlock() {
106		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
107	}
108	
109	func (s *Store) load() error {
110		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
111		if err != nil {
112			if os.IsNotExist(err) {
113				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
114				return nil
115			}
116			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
117		}
118		if len(data) == 0 {
119			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
120			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
121			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
122			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
123		}
124		var st persistedState
125		if err := json.Unmarshal(data, &st); err != nil {
126			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
127		}
128		if st.Version != stateVersion {
129			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
130		}
131		if err := validateState(&st); err != nil {
132			return err
133		}
134		if st.Requests == nil {
135			st.Requests = map[string]*requestRecord{}
136		}
137		s.state = &st
138		return nil
139	}
140	
141	// validateState 检查台账的引用完整性与数量合法性：
142	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
143	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
144	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
145	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
146	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
147	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
148	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
149	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
150	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
151	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
152	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
153	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
154	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
155	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
156	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
157	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
158	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
159	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
160	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
161	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
162	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
163	//     不同版本、不同配方各自使用同一物料编号不受影响。
164	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
165	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
166	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
167	//   - 每个已保存批次的计划份数必须为正整数，且按该批次实际绑定的配方版本
168	//     计算，每种物料的应投量（每份克数 × 计划份数）都必须能精确表示到
169	//     千分之一克、且不超过 maxGramsMilli（9223372036854775.807 克）。
170	//     任一批次份数为零或负数，或任一物料的应投量无法精确表示/超出上限，
171	//     整份台账即视为损坏：不区分草稿、执行中还是已关闭，也不取决于本次
172	//     查询哪个批次——不能自动减少份数、改选其他配方版本或删除问题批次，
173	//     即使其他批次完整也不能放行。上限按每种物料分别判断：多种物料的
174	//     应投量相加超过上限不构成非法，单种物料恰好等于上限仍合法。
175	//   - 草稿批次不能带有任何投料记录：登记投料只允许操作执行中的批次，
176	//     草稿尚未开始执行，出现投料说明保存内容自相矛盾。任一草稿批次包含
177	//     至少一条投料，整份台账即视为损坏——即使这些投料的物料都属于绑定
178	//     版本、克数均为合法正数、累计实投恰好等于应投，也不能接受；不能
179	//     丢弃投料后当作干净草稿，不能把批次自动改为执行中或已关闭，也不
180	//     能替调用方改选配方版本来继续读取。台账里另有正常批次、调用方只
181	//     查询其他配方或批次，都不能绕过这项矛盾。没有投料的草稿不受影响；
182	//     执行中尚未投料、已关闭批次没有投料或仍有欠投超投都属正常。
183	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
184	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
185	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
186	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
187	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
188	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
189	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
190	func validateState(st *persistedState) error {
191		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
192		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
193		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
194		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
195		versions := make(map[recipeKey]bool, len(st.Recipes))
196		for _, r := range st.Recipes {
197			if r == nil {
198				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
199			}
200			key := recipeKey{r.RecipeNo, r.Version}
201			if versions[key] {
202				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
203					ErrCorruptData, r.RecipeNo, r.Version)
204			}
205			versions[key] = true
206		}
207		for _, r := range st.Recipes {
208			seen := make(map[string]bool, len(r.Materials))
209			for _, m := range r.Materials {
210				if seen[m.MaterialNo] {
211					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
212						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
213				}
214				seen[m.MaterialNo] = true
215				if m.GramsMilli <= 0 {
216					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
217						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
218				}
219			}
220		}
221		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
222		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
223		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
224		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
225		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
226		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
227		batchNos := make(map[string]bool, len(st.Batches))
228		for _, b := range st.Batches {
229			if b == nil {
230				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
231			}
232			if batchNos[b.BatchNo] {
233				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
234			}
235			batchNos[b.BatchNo] = true
236		}
237		for _, b := range st.Batches {
238			// 草稿尚未开始执行，不能登记投料；已保存的草稿却带着投料，
239			// 说明记录自相矛盾。必须先于配方归属与数量校验拒绝——否则
240			// 这份草稿还能被打开、调整份数或改选配方版本，留下按旧计划
241			// 登记的投料。不能丢弃投料当作干净草稿，不能自动改状态，也
242			// 不能改选版本后继续。
243			if b.Status == StatusDraft && len(b.Feedings) > 0 {
244				return fmt.Errorf("%w: 批次 %q 仍为草稿状态，却存在 %d 条投料记录",
245					ErrCorruptData, b.BatchNo, len(b.Feedings))
246			}
247			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
248			if r == nil {
249				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
250					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
251			}
252			if err := validateBatchPlan(b, r); err != nil {
253				return err
254			}
255			if err := validateFeedings(b, r); err != nil {
256				return err
257			}
258		}
259		return nil
260	}
261	
262	// validateBatchPlan 检查一个已保存批次的计划份数与按绑定配方版本算出的
263	// 应投量。份数必须为正整数；配方版本 r 的每种物料按其每份克数乘以份数
264	// 得到的应投量都必须能以千分之一克精确表示且不超过 maxGramsMilli。
265	// 归属以批次实际绑定的版本为准：换用同编号的其他版本或许能算得通，也
266	// 不能作为接受依据。上限逐种物料判断，物料之间不相加；恰好等于上限合法。
267	// 计划数量是否合法与投料无关：尚未投料、实投不足或超出应投都不影响。
268	func validateBatchPlan(b *batchRecord, r *recipeRecord) error {
269		if b.PlannedPortions <= 0 {
270			return fmt.Errorf("%w: 批次 %q 的计划份数 %d 不是正整数",
271				ErrCorruptData, b.BatchNo, b.PlannedPortions)
272		}
273		for _, m := range r.Materials {
274			if _, err := multiplyPortions(m.GramsMilli, b.PlannedPortions); err != nil {
275				return fmt.Errorf("%w: 批次 %q（计划份数 %d）物料 %q 按绑定配方 %q 版本 %q 的应投量不合法: %v",
276					ErrCorruptData, b.BatchNo, b.PlannedPortions, m.MaterialNo,
277					b.RecipeNo, b.RecipeVersion, err)
278			}
279		}
280		return nil
281	}
282	
283	// validatePlanForRecipe 校验创建或调整草稿批次时，给定份数按配方版本逐
284	// 物料计算的应投量都能精确表示到千分之一克且不超过上限。份数本身的正
285	// 整数检查由调用方按各自输入规则完成（调整草稿时份数传 0 表示不改份数，
286	// 走到这里的必是最终采用的正份数），这里只判断数量范围。
287	func validatePlanForRecipe(r *recipeRecord, portions int) error {
288		for _, m := range r.Materials {
289			if _, err := multiplyPortions(m.GramsMilli, portions); err != nil {
290				return fmt.Errorf("物料 %q 按配方 %q 版本 %q 以 %d 份计算的应投量不合法: %v",
291					m.MaterialNo, r.RecipeNo, r.Version, portions, err)
292			}
293		}
294		return nil
295	}
296	
297	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
298	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
299	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
300	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
301	// 在此拒绝。
302	func validateFeedings(b *batchRecord, r *recipeRecord) error {
303		acc := newFeedingAccumulator()
304		for _, f := range b.Feedings {
305			belongs := false
306			for _, m := range r.Materials {
307				if m.MaterialNo == f.MaterialNo {
308					belongs = true
309					break
310				}
311			}
312			if !belongs {
313				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
314					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
315			}
316			if f.GramsMilli <= 0 {
317				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
318					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
319			}
320			if !acc.add(f.MaterialNo, f.GramsMilli) {
321				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
322					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
323			}
324		}
325		return nil
326	}
327	
328	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
329	func (s *Store) persist(st *persistedState) error {
330		data, err := json.MarshalIndent(st, "", "  ")
331		if err != nil {
332			return err
333		}
334		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
335		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
336		if err != nil {
337			return err
338		}
339		if _, err := f.Write(data); err != nil {
340			f.Close()
341			return err
342		}
343		if err := f.Sync(); err != nil {
344			f.Close()
345			return err
346		}
347		if err := f.Close(); err != nil {
348			return err
349		}
350		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
351			return err
352		}
353		if d, err := os.Open(s.dir); err == nil {
354			_ = d.Sync()
355			_ = d.Close()
356		}
357		return nil
358	}
359	
360	func cloneState(st *persistedState) (*persistedState, error) {
361		data, err := json.Marshal(st)
362		if err != nil {
363			return nil, err
364		}
365		var out persistedState
366		if err := json.Unmarshal(data, &out); err != nil {
367			return nil, err
368		}
369		if out.Requests == nil {
370			out.Requests = map[string]*requestRecord{}
371		}
372		return &out, nil
373	}
374	
375	// write 是所有写入操作的统一入口：
376	//   - reqNo 为空直接报错；
377	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
378	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
379	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
380	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
381	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
382		if reqNo == "" {
383			return errors.New("请求编号不能为空")
384		}
385		s.mu.Lock()
386		defer s.mu.Unlock()
387		if err := s.lockExclusive(); err != nil {
388			return err
389		}
390		defer s.unlock()
391	
392		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
393		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
394		if err := s.load(); err != nil {
395			return err
396		}
397	
398		payloadRaw, err := json.Marshal(payload)
399		if err != nil {
400			return err
401		}
402		payloadStr := string(payloadRaw)
403	
404		if req, ok := s.state.Requests[reqNo]; ok {
405			if req.Op != op || req.Payload != payloadStr {
406				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
407					ErrRequestConflict, reqNo, req.Op, op)
408			}
409			if err := json.Unmarshal(req.Result, out); err != nil {
410				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
411			}
412			return nil
413		}
414	
415		clone, err := cloneState(s.state)
416		if err != nil {
417			return err
418		}
419		result, err := apply(clone)
420		if err != nil {
421			return err
422		}
423		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
424		if err := s.persist(clone); err != nil {
425			return fmt.Errorf("保存台账失败: %w", err)
426		}
427		s.state = clone
428		if err := json.Unmarshal(result, out); err != nil {
429			return fmt.Errorf("解析请求结果失败: %w", err)
430		}
431		return nil
432	}
433	
434	// read 在共享锁下读取当前状态。
435	func (s *Store) read(fn func(*persistedState) error) error {
436		s.mu.Lock()
437		defer s.mu.Unlock()
438		if err := s.lockShared(); err != nil {
439			return err
440		}
441		defer s.unlock()
442		if err := s.load(); err != nil {
443			return err
444		}
445		return fn(s.state)
446	}
447	
448	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
449	
450	func buildRecipeView(r *recipeRecord) *RecipeView {
451		mats := make([]MaterialView, 0, len(r.Materials))
452		for _, m := range r.Materials {
453			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
454		}
455		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
456	}
457	
458	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
459		v := &BatchView{
460			BatchNo:         b.BatchNo,
461			RecipeNo:        r.RecipeNo,
462			RecipeVersion:   r.Version,
463			RecipeName:      r.Name,
464			PlannedPortions: b.PlannedPortions,
465			Status:          b.Status,
466			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
467			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
468		}
469	
470		for _, f := range b.Feedings {
471			v.Feedings = append(v.Feedings, FeedingView{
472				Seq:        f.Seq,
473				MaterialNo: f.MaterialNo,
474				Grams:      f.GramsMilli.String(),
475				Time:       f.Time,
476				Registrar:  f.Registrar,
477			})
478		}
479	
480		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
481		// 这里仍用同一套累计规则防一手整数回绕。
482		acc := newFeedingAccumulator()
483		for _, f := range b.Feedings {
484			if !acc.add(f.MaterialNo, f.GramsMilli) {
485				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
486					ErrCorruptData, b.BatchNo, f.MaterialNo)
487			}
488		}
489	
490		// 数量核对按配方物料逐项列出；台账在读取时已通过 validateState 校验，
491		// 这里仍防一手同一版本内物料编号重复，避免返回重复的数量核对项。
492		seen := make(map[string]bool, len(r.Materials))
493		for _, m := range r.Materials {
494			if seen[m.MaterialNo] {
495				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
496					ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
497			}
498			seen[m.MaterialNo] = true
499			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
500			if err != nil {
501				return nil, fmt.Errorf("%w: 批次 %q（计划份数 %d）物料 %q 的应投量不合法: %v",
502					ErrCorruptData, b.BatchNo, b.PlannedPortions, m.MaterialNo, err)
503			}
504			act := acc.total(m.MaterialNo)
505			v.Materials = append(v.Materials, MaterialRequirement{
506				MaterialNo:      m.MaterialNo,
507				RequiredGrams:   required.String(),
508				ActualGrams:     act.String(),
509				DifferenceGrams: (act - required).String(),
510			})
511		}
512		return v, nil
513	}
514	
515	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
516	type recipeKey struct {
517		recipeNo string
518		version  string
519	}
520	
521	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
522		for _, r := range st.Recipes {
523			if r.RecipeNo == recipeNo && r.Version == version {
524				return r
525			}
526		}
527		return nil
528	}
529	
530	func findBatch(st *persistedState, batchNo string) *batchRecord {
531		for _, b := range st.Batches {
532			if b.BatchNo == batchNo {
533				return b
534			}
535		}
536		return nil
537	}
538

