602	
603		// 先用非法内容提交（份数 0），失败。
604		if _, err := s.CreateBatch("x1", "B1", "R1", "v1", 0); !errors.Is(err, ErrInvalidInput) {
605			t.Fatalf("应失败，得到 %v", err)
606		}
607		// 同一编号用于合法内容，应成功。
608		if _, err := s.CreateBatch("x1", "B1", "R1", "v1", 10); err != nil {
609			t.Fatalf("失败不应占用编号，合法提交应成功: %v", err)
610		}
611	
612		// 投料失败（非配方物料）后，同编号合法投料成功。
613		if _, err := s.StartBatch("s1", "B1"); err != nil {
614			t.Fatal(err)
615		}
616		if _, err := s.AddFeeding("x2", "B1", "M9", "10", time.Now(), "张三"); !errors.Is(err, ErrMaterialNotInRecipe) {
617			t.Fatalf("应失败，得到 %v", err)
618		}
619		if _, err := s.AddFeeding("x2", "B1", "M1", "10", time.Now(), "张三"); err != nil {
620			t.Fatalf("失败不应占用编号，合法投料应成功: %v", err)
621		}
622		got, _ := s.GetBatch("B1")
623		if len(got.Feedings) != 1 || got.Feedings[0].Seq != 1 {
624			t.Fatalf("投料应成功登记一次: %+v", got.Feedings)
625		}
626	}
627	
628	// 并发：不同请求编号的投料全部生效，互不覆盖。
629	func TestConcurrentFeedings(t *testing.T) {
630		s := openTestStore(t)
631		registerStandardRecipe(t, s, "recipe-1")
632		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
633			t.Fatal(err)
634		}
635		if _, err := s.StartBatch("s1", "B1"); err != nil {
636			t.Fatal(err)
637		}
638	
639		const n = 50
640		var wg sync.WaitGroup
641		errs := make(chan error, n)
642		for i := 0; i < n; i++ {
643			wg.Add(1)
644			go func(i int) {
645				defer wg.Done()
646				_, err := s.AddFeeding(fmt.Sprintf("f-%03d", i), "B1", "M1", "1", time.Now(),
647					fmt.Sprintf("登记人%d", i))
648				errs <- err
649			}(i)
650		}
651		wg.Wait()
652		close(errs)
653		for err := range errs {
654			if err != nil {
655				t.Fatalf("并发投料失败: %v", err)
656			}
657		}
658	
659		got, err := s.GetBatch("B1")
660		if err != nil {
661			t.Fatal(err)
662		}
663		if len(got.Feedings) != n {
664			t.Fatalf("应有 %d 条投料，得到 %d", n, len(got.Feedings))
665		}
666		seqs := map[int]bool{}
667		for _, f := range got.Feedings {
668			if seqs[f.Seq] {
669				t.Fatalf("投料序号重复: %d", f.Seq)
670			}
671			seqs[f.Seq] = true
672		}
673		if len(seqs) != n {
674			t.Fatalf("投料序号应互不相同，得到 %d 个", len(seqs))
675		}
676		if got.Materials[0].ActualGrams != "50" {
677			t.Fatalf("累计实投应为 50，得到 %s", got.Materials[0].ActualGrams)
678		}
679	}
