681	// 并发：同一请求同时到达，只产生一次业务变更。
682	func TestConcurrentSameRequest(t *testing.T) {
683		s := openTestStore(t)
684		registerStandardRecipe(t, s, "recipe-1")
685		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
686			t.Fatal(err)
687		}
688		if _, err := s.StartBatch("s1", "B1"); err != nil {
689			t.Fatal(err)
690		}
691	
692		const n = 20
693		fixedTime := time.Date(2026, 6, 1, 10, 0, 0, 0, time.UTC)
694		var wg sync.WaitGroup
695		errs := make(chan error, n)
696		start := make(chan struct{})
697		for i := 0; i < n; i++ {
698			wg.Add(1)
699			go func() {
700				defer wg.Done()
701				<-start
702				_, err := s.AddFeeding("same-req", "B1", "M1", "10", fixedTime, "张三")
703				errs <- err
704			}()
705		}
706		close(start)
707		wg.Wait()
708		close(errs)
709		for err := range errs {
710			if err != nil {
711				t.Fatalf("并发相同请求应全部成功（重放），得到 %v", err)
712			}
713		}
714	
715		got, err := s.GetBatch("B1")
716		if err != nil {
717			t.Fatal(err)
718		}
719		if len(got.Feedings) != 1 {
720			t.Fatalf("同一请求只应产生一次投料，得到 %d 条", len(got.Feedings))
721		}
722		if got.Feedings[0].Grams != "10" {
723			t.Fatalf("投料内容不正确: %+v", got.Feedings[0])
724		}
725	}
