795		// 合法 JSON 但版本不受支持。
796		if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte(`{"version":99,"recipes":[],"batches":[],"requests":{}}`), 0o644); err != nil {
797			t.Fatal(err)
798		}
799		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
800			t.Fatalf("不支持的版本应返回 ErrCorruptData，得到 %v", err)
801		}
802	
803		// 空文件不等于“没有台账文件”，按损坏处理，不能当成空台账。
804		if err := os.WriteFile(filepath.Join(dir, "ledger.json"), []byte{}, 0o644); err != nil {
805			t.Fatal(err)
806		}
807		s2, err := Open(dir)
808		if !errors.Is(err, ErrCorruptData) {
809			t.Fatalf("零字节台账应返回 ErrCorruptData，得到 %v", err)
810		}
811		if s2 != nil {
812			s2.Close()
813			t.Fatalf("损坏台账不应返回可用的 Store 对象")
814		}
815		if !strings.Contains(err.Error(), "没有内容") {
816			t.Fatalf("错误信息应说明台账文件没有内容，得到 %v", err)
817		}
