		}()
	}
	close(start)
	wg.Wait()
	close(errs)
	for err := range errs {
		if err != nil {
			t.Fatalf("并发相同请求应全部成功（重放），得到 %v", err)
		}
	}

	got, err := s.GetBatch("B1")
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Feedings) != 1 {
